// Subflow DT session : sortie 1 = msg.dtUser (autorisé), sortie 2 = 401/403 prêt pour http response
// OUTIL vide = session seule (portail, /auth/me)
const outil = env.get('OUTIL') || '';

function refus(code, erreur, effacer) {
    msg.statusCode = code;
    msg.headers = { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' };
    msg.payload = { erreur };
    if (effacer) msg.cookies = { dt_session: { value: '', maxAge: 0, path: '/data-tools', httpOnly: true, secure: true, sameSite: 'strict' } };
    return [null, msg];
}

const P = global.get('dt_params') || {};
const gl = (P.sessionGlissanteH || 12) * 3600e3, mx = (P.sessionMaxH || 24) * 3600e3;
const jeton = ((msg.req && msg.req.cookies) || {}).dt_session;
if (typeof jeton !== 'string' || jeton.length < 20 || jeton.length > 100) return refus(401, 'non_authentifie', !!jeton);

const cle = crypto.createHash('sha256').update(jeton).digest('hex');
const S = global.get('dt_sessions') || {};
const s = S[cle];
const now = Date.now();
if (!s || now - s.vu > gl || now - s.cree > mx) {
    if (s) { delete S[cle]; global.set('dt_sessions', S); }
    return refus(401, 'non_authentifie', true);
}
if (now - s.vu > 60000) { s.vu = now; global.set('dt_sessions', S); }

if (outil && !(s.outils.includes('*') || s.outils.includes(outil))) return refus(403, 'acces_refuse');

const methode = String(msg.req.method || 'GET').toUpperCase();
if (methode !== 'GET' && methode !== 'HEAD' && msg.req.headers['x-dt'] !== '1') return refus(403, 'entete_x_dt_manquant');

msg.dtUser = { login: s.login, nom: s.nom, admin: !!s.admin, outils: [...s.outils] };
return [msg, null];

// @ts-nocheck
/* =========================================================
   Livraisons : collecte Business Central
   Entrées : inject nuit / deploy, demande "recharger" data-tools, réponses du nœud http request
   Sorties : 1 -> http request, 2 -> construction du modèle
   ========================================================= */
const C = {
  base: 'https://api.businesscentral.dynamics.com/v2.0/ef2c50ef-b9e0-499b-a90d-d7b2399d6ec4/Production/ODataV4/',
  // sociétés lues (ordre = ordre des puces Sociétés de la page). Retirer celles qui ne livrent pas.
  soc: [
    { nom: 'AGRIVALOR TRANSPORT ET SERVICE', court: 'TRANSPORT' },
    { nom: 'AGRIVALOR', court: 'AGRIVALOR' },
    { nom: 'AGRIVALOR BERGHEIM', court: 'BERGHEIM' },
    { nom: 'AGRIVALOR WITTENHEIM', court: 'WITTENHEIM' },
    { nom: 'AGRIVALOR EGUISHEIM', court: 'EGUISHEIM' },
    { nom: 'AGRIVALOR ENERGIE', court: 'ENERGIE' },
    { nom: 'CENTRALSACE COMPOST', court: 'CENTRALSACE' },
    { nom: 'SUNDGAU COMPOST', court: 'SUNDGAU' },
    { nom: 'ECO BOIS ALSACE', court: 'ECO BOIS' }
  ],
  depuis: '2025-01-01',      // historique chargé (date de tournée, de pesée ou de BL)

  // kg par unité de mesure, pour les missions et les BL sans pesée
  poidsUnite: { T: 1000, TO: 1000, TN: 1000, TON: 1000, TONNE: 1000, TONNES: 1000, KG: 1, KGS: 1, Q: 100, QX: 100, QL: 100 },
  // kg par unité pour un article précis (prioritaire). Ex. { '000506|STERE': 450, '000611|M3': 600 }
  poidsArticle: {},
  // secteur : préfixe de code postal -> secteur (le plus long gagne), sinon département
  // ex. { '681': 'Sundgau', '6820': 'Mulhouse', '67': 'Bas-Rhin' }
  secteursCP: {},
  // libellés des chauffeurs absents de la fiche ressource : { 'APER': 'Prénom Nom' }
  nomsChauffeurs: {},
  clientsExclus: [],         // clients jamais comptés (ex. intersociété)
  concurrence: 8, top: 5000, timeout: 300000, relances: 4, attente: [5000, 15000, 30000, 60000], maxRun: 45 * 60000
};
const D0 = C.depuis;
// Pages BC (Business Central > Services web), noms relevés par le scan des entités du 28/09/2026.
// Sans $select sauf pour les grosses pages : tous les champs publiés vont au modèle et à l'export Excel.
// principal : un 400/403/404 (page absente) est signalé, une panne réseau ou BC garde l'ancien modèle.
// unique : table commune à toutes les sociétés (champ Company_Name), lue une seule fois dans la 1re société.
//          Mettre unique: false si le journal montre des volumes différents d'une société à l'autre.
const E = {
  // 1. pesées : poids net, chauffeur, véhicule, tournée, client, article, sens (Output = sortie, Input = entrée)
  pesees: { ent: 'Écritures_journal_de_pesée_Excel', filter: `Creation_Date ge ${D0}T00:00:00Z`, principal: true },
  // 2. missions de transport : livraisons et collectes, tournée, véhicule, produit, origine et destination
  missions: { ent: 'Mission_Excel', filter: `Tour_Date ge ${D0}`, principal: true, unique: true },
  // 3. bons de livraison : entêtes (page Expédition vente enregistrée) et lignes (écritures article des expéditions)
  bl: { ent: 'Expédition_vente_enregistrée_Excel', filter: `Posting_Date ge ${D0}`, principal: true },
  blL: { ent: 'ItemLedgerEntries', filter: `Document_Type eq 'Sales Shipment' and Posting_Date ge ${D0}`, sel: 'Entry_No,Item_No,Posting_Date,Document_No,Document_Type,Location_Code,Quantity,Unit_of_Measure_Code,Qty_per_Unit_of_Measure,Item_Description,Job_No', principal: true },
  // compléments
  attente: { ent: 'Missions_non_affectées_Excel', optionnel: true, unique: true },                                     // carnet : missions à planifier
  cmdL: { ent: 'Lignes_vente_Excel', filter: "Document_Type eq 'Order' and Outstanding_Quantity gt 0", optionnel: true },  // carnet : reste à livrer des commandes
  cmd: { ent: 'Commande_vente_Excel', filter: "Document_Type eq 'Order'", sel: 'No,Order_Date,Sell_to_Customer_No,Sell_to_Customer_Name,Ship_to_Name,Ship_to_Post_Code,Ship_to_City,Sell_to_Post_Code,Sell_to_City,Shipment_Date,Location_Code,Status', optionnel: true },
  chauffeurs: { ent: 'Fiche_ressource_Excel', filter: "Type eq 'Driver'", sel: 'No,Name,Type,Resource_Group_No,Company_Name_WCAP,Vehicle_No_WCAP', optionnel: true },
  articles: { ent: 'Fiche_article_Excel', sel: 'No,Description,Type,Base_Unit_of_Measure,Net_Weight,Gross_Weight,Item_Category_Code,Activity_Description_PTE,Family_Description_PTE,Sub_Family_Description_PTE,Service_Type_WCAP', optionnel: true },
  adresses: { ent: 'Liste_adresses_destinataire', sel: 'Customer_No_PTE,Code,Name,Post_Code,City', optionnel: true },
  clients: { ent: 'Fiche_client_Excel', sel: 'No,Name,Post_Code,City,Salesperson_Code,Customer_Type_PTE', optionnel: true }
};
const RUN = 'lv_run';

function jobUrl(j) {
  const e = E[j.key], q = [];
  if (e.sel && !j.noSel) q.push('$select=' + e.sel);
  if (e.filter && !j.noFilter) q.push('$filter=' + encodeURIComponent(e.filter));
  q.push('$top=' + C.top);
  if (j.skip) q.push('$skip=' + j.skip);
  return C.base + "Company('" + encodeURIComponent(C.soc[j.pf].nom) + "')/" + encodeURIComponent(e.ent) + '?' + q.join('&');
}
function auth() {
  let t = global.get('TokenBC');
  if (t && typeof t === 'object') t = t.access_token || t.token || '';
  t = String(t || '');
  return /^bearer /i.test(t) ? t : 'Bearer ' + t;
}
function toHttp(j, R) {
  return {
    url: j.url || jobUrl(j), requestTimeout: C.timeout,
    headers: { Authorization: auth(), Accept: 'application/json', 'Data-Access-Intent': 'ReadOnly' },
    lv: { run: R.id, job: j }
  };
}
function pump(R) {
  const out = [];
  while (R.active < C.concurrence && R.queue.length) { R.active++; out.push(toHttp(R.queue.shift(), R)); }
  return out.length ? out : null;
}
const nbRows = R => { let n = 0; for (const k in R.stats) for (const v of R.stats[k]) n += v; return n; };
function errTxt(m) {
  const p = m.payload;
  if (p && typeof p === 'object' && p.error) return `${m.statusCode} ${p.error.code || ''} ${p.error.message || ''}`.trim();
  return `${m.statusCode || '?'} ${String(p || '').slice(0, 300)}`;
}

function start(origine) {
  const R0 = flow.get(RUN);
  if (R0 && !R0.fini && Date.now() - R0.t0 < C.maxRun) {
    node.warn('Livraisons : chargement déjà en cours, demande ignorée');
    return [null, null];
  }
  if (!global.get('TokenBC')) {
    node.error('Livraisons : global TokenBC absent, chargement annulé');
    node.status({ fill: 'red', shape: 'ring', text: 'TokenBC absent' });
    return [null, null];
  }
  const R = { id: Date.now().toString(36), t0: Date.now(), origine, queue: [], active: 0, done: 0, total: 0, pages: 0, raw: {}, stats: {}, errors: [], alerts: [], filtresClient: [], fini: false };
  for (const k in E) { R.raw[k] = C.soc.map(() => []); R.stats[k] = C.soc.map(() => 0); }
  // les grosses entités d'abord pour lisser la fin de collecte
  const ordre = ['blL', 'pesees', 'missions', 'bl', 'cmdL', 'attente', 'articles', 'clients', 'adresses', 'cmd', 'chauffeurs'].filter(k => E[k]);
  for (const k of ordre) C.soc.forEach((s, pf) => { if (!E[k].unique || pf === 0) R.queue.push({ key: k, pf, page: 1, try: 0, skip: 0 }); });
  R.total = R.queue.length;
  flow.set(RUN, R);
  node.status({ fill: 'blue', shape: 'dot', text: `collecte 0/${R.total} (${origine})` });
  return [pump(R), null];
}

function finish(R, out1) {
  R.fini = true;
  for (const ke in R.optEchecs || {}) R.alerts.push(`${ke} (${R.optEchecs[ke].join(', ')}) : page non lue`);
  const ms = Date.now() - R.t0;
  const payload = { raw: R.raw, C, E, stats: R.stats, errors: R.errors, alerts: R.alerts, manquants: R.manquants || [], filtresClient: R.filtresClient, ms, pages: R.pages, origine: R.origine, runId: R.id };
  flow.set(RUN, { id: R.id, t0: R.t0, fini: true, ms, done: R.done, total: R.total, errors: R.errors.length });
  node.status({ fill: R.errors.length ? 'yellow' : 'green', shape: 'dot', text: `${R.pages} pages, ${nbRows(R)} lignes, ${Math.round(ms / 1000)} s${R.errors.length ? ', ' + R.errors.length + ' erreurs' : ''}` });
  return [out1, { payload }];
}
function fin(R) {
  R.active--; R.done++;
  const out1 = pump(R);
  flow.set(RUN, R);
  if (!R.active && !R.queue.length) return finish(R, out1);
  if (R.done % 5 === 0) node.status({ fill: 'blue', shape: 'dot', text: `collecte ${R.done}/${R.total}` });
  return [out1, null];
}

function onResp() {
  const R = flow.get(RUN);
  if (!R || R.fini || msg.lv.run !== R.id) return null;           // réponse d'un chargement obsolète
  const j = msg.lv.job, sc = Number(msg.statusCode), pl = msg.payload;
  const lib = `${E[j.key].ent} / ${C.soc[j.pf].nom} page ${j.page}`;
  if (sc >= 200 && sc < 300 && pl && typeof pl === 'object' && Array.isArray(pl.value)) {
    const dst = R.raw[j.key][j.pf];
    for (const r of pl.value) dst.push(r);
    R.stats[j.key][j.pf] += pl.value.length; R.pages++;
    const nx = pl['@odata.nextLink'];
    if (nx) { R.queue.unshift(Object.assign({}, j, { url: nx, page: j.page + 1, try: 0, mode: 'next' })); R.total++; }
    else if (j.mode !== 'next' && pl.value.length >= C.top) { R.queue.unshift(Object.assign({}, j, { url: null, skip: (j.skip || 0) + C.top, page: j.page + 1, try: 0 })); R.total++; }
    return fin(R);
  }
  const err = errTxt(msg);
  // 400 sur une page lue : une relance sans $select, puis une sans $filter (filtre appliqué au modèle)
  if (sc === 400 && !j.url && ((E[j.key].sel && !j.noSel) || (E[j.key].filter && !j.noFilter))) {
    if (E[j.key].sel && !j.noSel) { j.noSel = true; R.alerts.push(`${lib} : $select refusé par BC (${err}), relancé sans $select`); }
    else {
      j.noFilter = true;
      R.alerts.push(`${lib} : $filter refusé par BC (${err}), relancé sans filtre (filtre appliqué après lecture)`);
      if (!R.filtresClient.includes(j.key)) R.filtresClient.push(j.key);
    }
    flow.set(RUN, R);
    return [[toHttp(j, R)], null];
  }
  if (![400, 403, 404].includes(sc) && j.try < C.relances) {
    j.try++;
    let w = C.attente[Math.min(j.try - 1, C.attente.length - 1)];
    const ra = msg.headers && Number(msg.headers['retry-after']);
    if (ra > 0) w = Math.max(w, ra * 1000);
    node.status({ fill: 'yellow', shape: 'ring', text: `relance ${j.try}/${C.relances} dans ${w / 1000} s : ${lib}` });
    const id = R.id;
    setTimeout(() => {
      const R2 = flow.get(RUN);
      if (!R2 || R2.id !== id || R2.fini) return;
      node.send([toHttp(j, R2), null]);
    }, w);
    return null;
  }
  // page absente ou refusée, ou entité complémentaire : signalé sans bloquer la mise à jour
  if (E[j.key].optionnel || [400, 403, 404].includes(sc)) {
    // regroupé par page BC et par erreur (une alerte pour toutes les sociétés concernées)
    const ke = E[j.key].ent + ' : ' + err;
    R.optEchecs = R.optEchecs || {};
    (R.optEchecs[ke] || (R.optEchecs[ke] = [])).push(C.soc[j.pf].court);
    R.manquants = (R.manquants || []).concat(j.key + '|' + j.pf);
    return fin(R);
  }
  R.errors.push(`${lib} : ${err}${j.try ? ` (après ${j.try} relances)` : ''}`);
  return fin(R);
}

if (msg.lv) return onResp();
return start(msg.topic || 'manuel');

initialize:
// Redeploy pendant une collecte : les minuteries sont perdues, on libère le verrou
const R = flow.get('lv_run');
if (R && !R.fini) flow.set('lv_run', { id: 'reset', fini: true });

