// @ts-nocheck
/* =========================================================
   Livraisons : construction du modèle en mémoire (fonction pure)
   buildModel(raw, C) -> { M, J }
   raw : { cle_entite: [lignesSociete0, lignesSociete1, ...] }
   Trois sources, analysées séparément (jamais additionnées) :
   - pesees   : une pesée terminée = un passage sur pont-bascule (poids net, chauffeur, véhicule, tournée)
   - missions : une mission de transport (livraison ou collecte), quantité produit
   - bl       : un bon de livraison BC (expédition vente), lignes = écritures article de l'expédition
   ========================================================= */
function buildModel(raw, C) {
  const t0 = Date.now();
  const J = { rejets: {}, ignores: {}, dedup: [], alertes: [], totaux: [] };
  const rej = (m, n = 1) => { if (n) J.rejets[m] = (J.rejets[m] || 0) + n; };
  const ign = (m, n = 1) => { if (n) J.ignores[m] = (J.ignores[m] || 0) + n; };
  const S = x => (x === null || x === undefined ? '' : String(x).trim());
  const N = x => { const n = Number(x); return isFinite(n) ? n : 0; };
  const D = x => { const s = S(x).slice(0, 10); return /^\d{4}-\d{2}-\d{2}$/.test(s) && s > '1900-01-01' ? s : ''; };
  const r2 = x => Math.round((x + (x >= 0 ? 1e-9 : -1e-9)) * 100) / 100;
  const pc = (a, b) => (b ? Math.round((a / b) * 1000) / 10 : 0);
  const npf = C.soc.length;
  const EXCL = new Set((C.clientsExclus || []).map(S));
  const pfDe = {}; C.soc.forEach((s, i) => (pfDe[s.nom.toUpperCase()] = i));
  const fmtP = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' });
  const jourParis = iso => { const d = new Date(iso); if (isNaN(d)) return ''; const o = {}; for (const x of fmtP.formatToParts(d)) o[x.type] = x.value; return `${o.year}-${o.month}-${o.day}`; };
  const today = jourParis(new Date().toISOString());
  for (const k of Object.keys(raw)) for (let pf = 0; pf < npf; pf++) if (!raw[k][pf]) raw[k][pf] = [];
  const flat = k => [].concat(...(raw[k] || []));

  /* 1. Doublons inter-sociétés : tables partagées (missions, pesées...) renvoyées à l'identique par chaque société */
  for (const k of Object.keys(raw)) {
    const seen = new Map(); const info = { entite: k, retires: 0, detail: [] };
    for (let pf = 0; pf < npf; pf++) {
      const rows = raw[k][pf]; const keep = []; let dup = 0;
      for (const r of rows) {
        delete r['@odata.etag'];
        const sig = JSON.stringify(r); const p = seen.get(sig);
        if (p !== undefined && p !== pf) { dup++; continue; }
        if (p === undefined) seen.set(sig, pf);
        keep.push(r);
      }
      raw[k][pf] = keep;
      if (dup) { info.retires += dup; info.detail.push(`${C.soc[pf].court} : ${dup}/${rows.length}`); }
    }
    if (info.retires) J.dedup.push(info);
  }

  /* 2. Référentiels : articles, chauffeurs, clients, adresses de livraison */
  const ART = {};
  flat('articles').forEach(r => {
    const a = S(r.No); if (!a || ART[a]) return;
    ART[a] = { lib: S(r.Description), pn: N(r.Net_Weight), cat: S(r.Family_Description_PTE) || S(r.Item_Category_Code), act: S(r.Activity_Description_PTE), sfam: S(r.Sub_Family_Description_PTE), ub: S(r.Base_Unit_of_Measure) };
  });
  const chaufLib = {}, chaufVeh = {};
  flat('chauffeurs').forEach(r => { const c = S(r.No); if (!c) return; chaufLib[c] = S(r.Name); if (S(r.Vehicle_No_WCAP)) chaufVeh[c] = S(r.Vehicle_No_WCAP); });
  for (const c in C.nomsChauffeurs || {}) if (!chaufLib[c]) chaufLib[c] = C.nomsChauffeurs[c];
  const noms = {}, CLI = {};
  flat('clients').forEach(r => { const c = S(r.No); if (!c) return; noms[c] = S(r.Name); CLI[c] = { cp: S(r.Post_Code), ville: S(r.City), vend: S(r.Salesperson_Code), type: S(r.Customer_Type_PTE) }; });
  const ADR = {};
  flat('adresses').forEach(r => { const k = S(r.Customer_No_PTE) + '|' + S(r.Code); ADR[k] = { nom: S(r.Name), cp: S(r.Post_Code), ville: S(r.City) }; });
  const artLib = {}; for (const a in ART) artLib[a] = ART[a].lib;
  const setLib = (a, l) => { if (a && l && !artLib[a]) artLib[a] = l; };
  const setNom = (c, n) => { if (c && n && !noms[c]) noms[c] = n; };
  // commune d'un code postal, apprise sur toutes les adresses connues
  const villeCP = {};
  const apprendre = (cp, v) => { if (cp && v && !villeCP[cp]) villeCP[cp] = v; };
  Object.values(ADR).forEach(a => apprendre(a.cp, a.ville));
  Object.values(CLI).forEach(a => apprendre(a.cp, a.ville));

  /* 3. Poids en kg : pesé, sinon poids par article (paramètre), unité de poids, poids net fiche article */
  const PU = {}; for (const k in C.poidsUnite || {}) PU[k.toUpperCase()] = N(C.poidsUnite[k]);
  const PA = C.poidsArticle || {};
  function poids(art, u, q) {
    const U = S(u).toUpperCase();
    if (PA[art + '|' + u] !== undefined) return { kg: q * N(PA[art + '|' + u]), s: 'Poids par article (paramètre)' };
    if (PU[U] !== undefined) return { kg: q * PU[U], s: 'Unité de poids (' + U + ')' };
    if (ART[art] && ART[art].pn > 0 && (!ART[art].ub || ART[art].ub === u)) return { kg: q * ART[art].pn, s: 'Poids net de la fiche article' };
    return { kg: 0, s: 'Sans poids' };
  }

  /* 4. Secteur : préfixe de code postal (paramètre), sinon département */
  const DEPTS = { '67': 'Bas-Rhin', '68': 'Haut-Rhin', '90': 'Territoire de Belfort', '25': 'Doubs', '70': 'Haute-Saône', '88': 'Vosges', '57': 'Moselle', '54': 'Meurthe-et-Moselle', '39': 'Jura', '21': "Côte-d'Or" };
  const SCP = Object.keys(C.secteursCP || {}).sort((a, b) => b.length - a.length);
  function secteur(cp, pays) {
    const c = S(cp).replace(/\s/g, '');
    for (const p of SCP) if (c.startsWith(p)) return C.secteursCP[p];
    if (/^\d{5}$/.test(c) && (!pays || /^(FR|FRANCE)$/i.test(pays))) { const d = c.slice(0, 2); return 'Dépt ' + d + (DEPTS[d] ? ' ' + DEPTS[d] : ''); }
    if (pays && !/^(FR|FRANCE)$/i.test(pays)) return 'Étranger ' + pays;
    return '?';
  }

  const srcPoids = { pesees: {}, missions: {}, bl: {} }, sansPoids = {};
  const notePoids = (src, s, kg, art, u, q, lib, pf) => {
    const x = srcPoids[src][s] || (srcPoids[src][s] = { s, lignes: 0, kg: 0 }); x.lignes++; x.kg += kg;
    if (s === 'Sans poids' && art) { const k = src + '|' + art + '|' + u; const y = sansPoids[k] || (sansPoids[k] = { src, art, lib, u, lignes: 0, q: 0, pfs: {} }); y.lignes++; y.q += q; y.pfs[pf] = 1; }
  };
  const societe = (type, code, defaut) => (/company/i.test(type) && pfDe[S(code).toUpperCase()] !== undefined ? pfDe[S(code).toUpperCase()] : defaut);

  /* 5. Pesées : une paire 1re / 2e pesée = un passage, valeurs prises sur la pesée terminée au poids net le plus fort */
  const P = { facts: [], docs: {}, raw: [] };
  const tourChauf = {};
  {
    const G = {};
    raw.pesees.forEach((rows, pf) => rows.forEach(r => {
      const e = N(r.Entry_No), rel = N(r.Related_Entry_No) || e;
      const k = Math.min(e, rel) || S(r.Mission_No) + '|' + S(r.Creation_Date);
      const g = G[k] || (G[k] = { pf, rows: [] }); g.rows.push(r);
    }));
    let nonFinies = 0;
    for (const k in G) {
      const fin = G[k].rows.filter(r => r.Finished === true || N(r.Net_Weight));
      if (!fin.length) { nonFinies++; continue; }
      const r = fin.sort((a, b) => Math.abs(N(b.Net_Weight)) - Math.abs(N(a.Net_Weight)))[0];
      const d = D(r.Tour_Date) || jourParis(r.First_Weighing_DateTime) || jourParis(r.Creation_Date);
      if (!d) { rej('pesée sans date'); continue; }
      if (d < C.depuis) { ign('pesée antérieure à la date de début'); continue; }
      const sortie = /output|sortie/i.test(S(r.Weighing_Direction));
      const cli = S(r.Customer_No) || (sortie ? S(r.Destination_Code) : S(r.Origin_Code));
      if (cli && EXCL.has(cli)) { ign('pesée d\'un client exclu'); continue; }
      setNom(cli, S(r.Customer_Name));
      const adrCode = sortie ? S(r.Destination_Address_Code) || S(r.Customer_Address_Code) : S(r.Origin_Address_Code);
      const adr = ADR[cli + '|' + adrCode];
      const cp = S(sortie ? r.Destination_Post_Code : r.Origin_Post_Code) || (adr ? adr.cp : '');
      const pays = S(sortie ? r.Destination_Country : r.Origin_Country);
      const ville = (adr && adr.ville) || villeCP[cp] || '';
      const pf = sortie ? societe(r.Origin_Type, r.Origin_Code, G[k].pf) : societe(r.Destination_Type, r.Destination_Code, G[k].pf);
      const kg = Math.abs(N(r.Net_Weight));
      const art = S(r.Item_No); setLib(art, S(r.Item_Description) || S(r.Item_Card_Description));
      const chauf = S(r.Driver_No), tour = S(r.Tour_No);
      if (tour && chauf) { const t = tourChauf[tour] || (tourChauf[tour] = {}); t[chauf] = (t[chauf] || 0) + 1; }
      const doc = 'P' + k;
      const ri = P.raw.length; P.raw.push(Object.assign({ _pf: pf }, r));
      const h = {
        pf, doc, no: S(r.Mission_No) || String(k), d, cli, nom: S(r.Customer_Name), livNom: S(sortie ? r.Destination_Name : r.Origin_Name), cp, ville, pays,
        sect: secteur(cp, pays), chauf: chauf || '?', veh: S(r.Vehicle_Plate_Number) || '?', rem: S(r.Trailer_Plate_Number), tour, tourLib: S(r.Tour_Description),
        transp: S(r.Carrier_Name) || S(r.Carrier_Code), lieu: S(sortie ? r.Origin_Name : r.Destination_Name), ord: S(r.Document_No), sens: sortie ? 'L' : 'C',
        brut: N(r.Gross_Weight), tare: N(r.Tare), kg, dCible: '', annule: false, ri
      };
      P.docs[doc] = h;
      notePoids('pesees', kg ? 'Poids net pesé' : 'Pesée à poids nul', kg, art, 'T', 0, '', pf);
      P.facts.push({ pf, bl: doc, d, cli, cp, ville, sect: h.sect, chauf: h.chauf, veh: h.veh, transp: h.transp, lieu: h.lieu, ord: h.ord, tour, sens: h.sens, ty: 'Pesée', art, u: 'T', q: kg / 1000, kg, ps: 'Poids net pesé', ht: 0, cat: ART[art] ? ART[art].cat : '', act: ART[art] ? ART[art].act : '', ri });
    }
    ign('pesée non terminée', nonFinies);
  }
  const chaufTour = t => { const m = tourChauf[t]; if (!m) return ''; return Object.keys(m).sort((a, b) => m[b] - m[a])[0]; };
  // véhicule -> chauffeur titulaire (fiche ressource), repli pour les missions sans pesée
  const vehChauf = {}; for (const c in chaufVeh) vehChauf[chaufVeh[c].replace(/[\s-]/g, '').toUpperCase()] = c;
  const parVeh = v => vehChauf[S(v).replace(/[\s-]/g, '').toUpperCase()] || '';

  /* 6. Missions de transport */
  const Mi = { facts: [], docs: {}, raw: [] };
  raw.missions.forEach((rows, pf0) => rows.forEach(r => {
    const no = S(r.No); if (!no) { rej('mission sans numéro'); return; }
    if (Mi.docs[no]) { ign('mission en double (même numéro)'); return; }
    const d = D(r.Tour_Date) || D(r.Requested_Date);
    if (!d) { ign('mission sans date de tournée'); return; }
    if (d < C.depuis) { ign('mission antérieure à la date de début'); return; }
    const coll = /pick|collect|enl/i.test(S(r.Service_Type_Direction));
    const pf = pfDe[S(r.Company_Name).toUpperCase()] !== undefined ? pfDe[S(r.Company_Name).toUpperCase()] : pf0;
    const ty = coll ? r.Origin_Type : r.Destination_Type, code = S(coll ? r.Origin_Code : r.Destination_Code);
    const cli = /customer/i.test(S(ty)) ? code : S(r.Bill_to_Third_party_No);
    if (cli && EXCL.has(cli)) { ign('mission d\'un client exclu'); return; }
    setNom(cli, S(coll ? r.Origin_Name : r.Destination_Name));
    const cp = S(coll ? r.Origin_Post_Code : r.Destination_Post_Code), ville = S(coll ? r.Origin_City : r.Destination_City) || villeCP[cp] || '';
    const pays = S(coll ? r.Origin_Country_Region_Code : r.Destination_Country_Region_Code);
    apprendre(cp, ville);
    const tour = S(r.Tour_No), chauf = chaufTour(tour) || parVeh(r.Tour_Vehicle_No);
    const art = S(r.Product_Item_No), u = S(r.Product_Unit_of_Measure);
    setLib(art, S(r.Product_Item_Description));
    const q = N(r.Actual_Delivered_Quantity) || N(r.Actual_Picked_Quantity) || N(r.Product_Quantity);
    const net = N(r.Total_Net_Weight) || N(r.Weight);
    const p = net > 0 ? { kg: net, s: 'Poids de la mission' } : poids(art, u, q);
    notePoids('missions', p.s, p.kg, art, u, q, S(r.Product_Item_Description), pf);
    const ri = Mi.raw.length; Mi.raw.push(Object.assign({ _pf: pf }, r));
    const h = {
      pf, doc: no, no, d, cli, nom: noms[cli] || S(coll ? r.Origin_Name : r.Destination_Name), livNom: S(coll ? r.Origin_Name : r.Destination_Name), cp, ville, pays,
      sect: secteur(cp, pays), chauf: chauf || '?', veh: S(r.Tour_Vehicle_No) || '?', tour, tourLib: S(r.Tour_Description),
      transp: S(r.Carrier_Code), lieu: S(coll ? r.Destination_Name : r.Origin_Name), ord: S(r.Purchase_Order_No), sens: coll ? 'C' : 'L',
      service: S(r.Service_Item_Description), type: S(r.Mission_Type), dCible: D(r.Requested_Date), vide: r.Empty_Run === true, controle: r.Controlled === true,
      remplissage: S(r.Fill_Rate), annule: false, ri
    };
    Mi.docs[no] = h;
    Mi.facts.push({ pf, bl: no, d, cli, cp, ville, sect: h.sect, chauf: h.chauf, veh: h.veh, transp: h.transp, lieu: h.lieu, ord: h.ord, tour, sens: h.sens, ty: h.service || 'Mission', art, u, q, kg: p.kg, ps: p.s, ht: 0, cat: ART[art] ? ART[art].cat : '', act: ART[art] ? ART[art].act : '', ri });
  }));

  /* 7. Bons de livraison : entête + écritures article de l'expédition ; chauffeur et véhicule repris des pesées de la commande */
  const B = { facts: [], docs: {}, raw: [] };
  const pesCmd = {};
  for (const k in P.docs) { const h = P.docs[k]; if (h.ord) (pesCmd[h.ord] || (pesCmd[h.ord] = [])).push(h); }
  raw.bl.forEach((rows, pf) => rows.forEach(h => {
    const no = S(h.No); if (!no) { rej('BL sans numéro'); return; }
    const d = D(h.Posting_Date) || D(h.Document_Date); if (!d) { rej('BL sans date'); return; }
    if (d < C.depuis) { ign('BL antérieur à la date de début'); return; }
    const cli = S(h.Sell_to_Customer_No); if (cli && EXCL.has(cli)) { ign('BL d\'un client exclu'); return; }
    setNom(cli, S(h.Sell_to_Customer_Name));
    const cp = S(h.Ship_to_Post_Code) || S(h.Sell_to_Post_Code), ville = S(h.Ship_to_City) || S(h.Sell_to_City), pays = S(h.Ship_to_Country_Region_Code) || S(h.Sell_to_Country_Region_Code);
    apprendre(cp, ville);
    const ord = S(h.Order_No);
    // pesée de la même commande, la plus proche en date
    const ps = (pesCmd[ord] || []).slice().sort((a, b) => Math.abs(Date.parse(a.d) - Date.parse(d)) - Math.abs(Date.parse(b.d) - Date.parse(d)));
    const pz = ps[0] && Math.abs(Date.parse(ps[0].d) - Date.parse(d)) <= 3 * 864e5 ? ps[0] : null;
    const ri = B.raw.length; B.raw.push(Object.assign({ _pf: pf }, h));
    B.docs[pf + '|' + no] = {
      pf, doc: pf + '|' + no, no, d, cli, nom: S(h.Sell_to_Customer_Name), livNom: S(h.Ship_to_Name), cp, ville, pays, sect: secteur(cp, pays),
      chauf: pz && pz.chauf !== '?' ? pz.chauf : '?', veh: pz ? pz.veh : '?', tour: pz ? pz.tour : '', tourLib: pz ? pz.tourLib : '', transp: S(h.Shipping_Agent_Code) || (pz ? pz.transp : ''),
      lieu: S(h.Location_Code), ord, ext: S(h.External_Document_No), vend: S(h.Salesperson_Code), sens: 'L',
      dCible: D(h.Promised_Delivery_Date) || D(h.Requested_Delivery_Date) || D(h.Shipment_Date), kgPese: pz ? ps.filter(x => x.d === pz.d).reduce((s, x) => s + x.kg, 0) : 0,
      lignes: 0, kg: 0, annule: false, ri
    };
  }));
  {
    const L = {};
    raw.blL.forEach((rows, pf) => rows.forEach(r => {
      if (!/shipment/i.test(S(r.Document_Type))) { ign('écriture article hors expédition'); return; }
      const k = pf + '|' + S(r.Document_No);
      if (!B.docs[k]) { const d = D(r.Posting_Date); if (d && d < C.depuis) ign('écriture article antérieure à la date de début'); else rej('écriture d\'expédition sans entête de BL (BL hors période, client exclu ou page entête absente)'); return; }
      (L[k] || (L[k] = [])).push(r);
    }));
    for (const k in B.docs) {
      const h = B.docs[k], rows = L[k];
      if (!rows) { ign('BL sans écriture article (lignes non article ou écritures non lues)'); delete B.docs[k]; continue; }
      const net = {};
      const lignes = rows.map(r => {
        const q = -N(r.Quantity) / (N(r.Qty_per_Unit_of_Measure) || 1), u = S(r.Unit_of_Measure_Code), art = S(r.Item_No);
        setLib(art, S(r.Item_Description));
        net[art + '|' + u] = (net[art + '|' + u] || 0) + q;
        return { r, q, u, art, p: poids(art, u, q) };
      });
      h.annule = Object.values(net).every(v => Math.abs(v) < 1e-9);
      const kgL = lignes.reduce((s, x) => s + x.p.kg, 0);
      // BL sans poids calculable mais pesé : poids de la pesée réparti au prorata des quantités
      const qTot = lignes.reduce((s, x) => s + Math.abs(x.q), 0);
      const pese = !kgL && h.kgPese > 0 && qTot > 0;
      for (const x of lignes) {
        const kg = pese ? h.kgPese * Math.abs(x.q) / qTot * Math.sign(x.q) : x.p.kg;
        const s = pese ? 'Pesée de la commande' : x.p.s;
        notePoids('bl', s, kg, x.art, x.u, x.q, artLib[x.art], h.pf);
        const ri = B.raw.length; B.raw.push(Object.assign({ _pf: h.pf, _ligne: true }, x.r));
        B.facts.push({ pf: h.pf, bl: k, d: h.d, cli: h.cli, cp: h.cp, ville: h.ville, sect: h.sect, chauf: h.chauf, veh: h.veh, transp: h.transp, lieu: S(x.r.Location_Code) || h.lieu, ord: h.ord, tour: h.tour, sens: 'L', ty: 'Article', art: x.art, u: x.u, q: x.q, kg, ps: s, ht: 0, cat: ART[x.art] ? ART[x.art].cat : '', act: ART[x.art] ? ART[x.art].act : '', ri });
        h.lignes++; h.kg += kg;
      }
    }
  }

  /* 8. Carnet : missions à planifier et reste à livrer des commandes ouvertes */
  const carnet = [];
  flat('attente').forEach(r => {
    const coll = /collect|enl/i.test(S(r.Service_Type_Description));
    const pf = pfDe[S(r.Company_Name).toUpperCase()] !== undefined ? pfDe[S(r.Company_Name).toUpperCase()] : 0;
    const cli = /customer/i.test(S(coll ? r.Origin_Type : r.Destination_Type)) ? S(coll ? r.Origin_Code : r.Destination_Code) : '';
    if (cli && EXCL.has(cli)) return;
    setNom(cli, S(coll ? r.Origin_Third_Party_Name : r.Destination_Third_Party_Name));
    const cp = S(coll ? r.Origin_Post_Code : r.Destination_Post_Code);
    const art = S(r.Product_Item_No), u = S(r.Product_Unit_of_Measure), q = N(r.Product_Quantity);
    setLib(art, S(r.Product_Item_Description));
    carnet.push({ src: 'Mission à planifier', pf, no: S(r.No), doc: S(r.Mission_Doc_No), dCmd: '', dPrev: D(r.Requested_Date), cli, cp, ville: S(coll ? r.Origin_City : r.Destination_City), sect: secteur(cp, ''), chauf: '?', veh: '?', sens: coll ? 'C' : 'L', art, u, q, qr: q, kg: poids(art, u, q).kg, ht: 0, obs: S(r.Observation) });
  });
  {
    const CMD = {};
    raw.cmd.forEach((rows, pf) => rows.forEach(h => { CMD[pf + '|' + S(h.No)] = h; }));
    raw.cmdL.forEach((rows, pf) => rows.forEach(l => {
      if (!S(l.Type) || S(l.Document_Type) !== 'Order') return;
      const qr = N(l.Outstanding_Quantity); if (!(qr > 0)) return;
      const h = CMD[pf + '|' + S(l.Document_No)] || {};
      const cli = S(l.Sell_to_Customer_No) || S(h.Sell_to_Customer_No); if (cli && EXCL.has(cli)) return;
      setNom(cli, S(l.Sell_to_Customer_Name) || S(h.Sell_to_Customer_Name));
      const art = S(l.No), u = S(l.Unit_of_Measure_Code); setLib(art, S(l.Description));
      const cp = S(h.Ship_to_Post_Code) || S(h.Sell_to_Post_Code) || (CLI[cli] || {}).cp || '';
      const qt = N(l.Quantity);
      carnet.push({ src: 'Commande à livrer', pf, no: S(l.Document_No), doc: S(l.Document_No), dCmd: D(h.Order_Date), dPrev: D(l.Shipment_Date) || D(h.Shipment_Date), cli, cp, ville: S(h.Ship_to_City) || S(h.Sell_to_City) || villeCP[cp] || '', sect: secteur(cp, ''), chauf: '?', veh: '?', sens: 'L', art, u, q: qt, qr, kg: poids(art, u, qr).kg, ht: qt ? N(l.Line_Amount) * qr / qt : 0, obs: '' });
    }));
  }
  carnet.sort((a, b) => ((a.dPrev || '9') < (b.dPrev || '9') ? -1 : (a.dPrev || '9') > (b.dPrev || '9') ? 1 : 0));

  /* 9. Contrôle de remplissage par source */
  const SRC = { pesees: P, missions: Mi, bl: B };
  const LIB = { pesees: 'Pesées', missions: 'Missions', bl: 'Bons de livraison' };
  const sources = {};
  for (const k in SRC) {
    const X = SRC[k]; X.facts.sort((a, b) => (a.d < b.d ? -1 : a.d > b.d ? 1 : 0));
    const docs = Object.values(X.docs), n = docs.length;
    const kgT = X.facts.reduce((s, f) => s + f.kg, 0);
    const sp = srcPoids[k]['Sans poids'] || { lignes: 0 };
    sources[k] = {
      lib: LIB[k], docs: n, lignes: X.facts.length, t: r2(kgT / 1000), dMin: X.facts.length ? X.facts[0].d : '', dMax: X.facts.length ? X.facts[X.facts.length - 1].d : '',
      remplissage: { chauf: docs.filter(h => h.chauf !== '?').length, veh: docs.filter(h => h.veh !== '?').length, cp: docs.filter(h => h.cp).length, ville: docs.filter(h => h.ville).length, cli: docs.filter(h => h.cli).length, tour: docs.filter(h => h.tour).length, cible: docs.filter(h => h.dCible).length, livr: docs.filter(h => h.sens === 'L').length },
      poids: Object.values(srcPoids[k]).map(x => ({ s: x.s, lignes: x.lignes, t: r2(x.kg / 1000), part: kgT ? x.kg / kgT : null })).sort((a, b) => b.lignes - a.lignes)
    };
    if (!n) J.alertes.push(`${LIB[k]} : aucune donnée chargée (page BC absente, vide ou hors période)`);
    else {
      if (k !== 'bl' && sources[k].remplissage.chauf < n * 0.5) J.alertes.push(`${LIB[k]} : chauffeur connu sur ${pc(sources[k].remplissage.chauf, n)} % seulement`);
      if (sp.lignes > X.facts.length * 0.05) J.alertes.push(`${LIB[k]} : ${sp.lignes} lignes sans poids (${pc(sp.lignes, X.facts.length)} %), voir l'onglet Contrôle`);
    }
    for (let pf = 0; pf < npf; pf++) {
      const ds = docs.filter(h => h.pf === pf && !h.annule);
      J.totaux.push({ source: LIB[k], societe: C.soc[pf].nom, docs: ds.length, tonnes: r2(X.facts.filter(f => f.pf === pf).reduce((s, f) => s + f.kg, 0) / 1000) });
    }
  }

  const M = {
    v: 2, loadedAt: new Date().toISOString(), today, depuis: C.depuis,
    pfs: C.soc.map(s => s.court), pfNoms: C.soc.map(s => s.nom),
    src: { pesees: { facts: P.facts, docs: P.docs, raw: P.raw }, missions: { facts: Mi.facts, docs: Mi.docs, raw: Mi.raw }, bl: { facts: B.facts, docs: B.docs, raw: B.raw } },
    carnet, noms, artLib, chaufLib, chaufVeh, art: ART, erreurs: [],
    controle: {
      sources, totaux: J.totaux, dedup: J.dedup, rejets: J.rejets, ignores: J.ignores, alertes: J.alertes,
      sansPoids: Object.values(sansPoids).map(x => Object.assign({}, x, { src: LIB[x.src], q: r2(x.q), pfs: Object.keys(x.pfs).map(Number) })).sort((a, b) => b.lignes - a.lignes).slice(0, 300),
      referentiels: { articles: Object.keys(ART).length, chauffeurs: Object.keys(chaufLib).length, clients: Object.keys(CLI).length, adresses: Object.keys(ADR).length },
      carnet: { missions: carnet.filter(c => c.src === 'Mission à planifier').length, commandes: carnet.filter(c => c.src !== 'Mission à planifier').length }
    }
  };
  J.volumes = {};
  for (const k in sources) J.volumes[k] = `${sources[k].docs} docs, ${sources[k].t} t`;
  J.volumes.carnet = carnet.length; J.volumes.chauffeurs = Object.keys(chaufLib).length;
  J.ms = Date.now() - t0;
  return { M, J };
}


/* =========================================================
   Traitement du message de la collecte
   Sortie : 1 -> debug "Journal de chargement"
   ========================================================= */
const P = msg.payload || {};
const C = Object.assign({}, P.C);
C.filtresClient = P.filtresClient || [];
const raw = P.raw || {};
const fr = n => Number(n).toLocaleString('fr-FR');

// 1. Collecte en échec avec un modèle déjà en mémoire : on garde l'ancien
const prev = flow.get('lv_M');
if (P.errors && P.errors.length && prev && prev.v === 2) {
  prev.erreurs = [`Rechargement du ${new Date().toLocaleString('fr-FR', { timeZone: 'Europe/Paris' })} en échec (${P.errors.length} requêtes) : données du ${new Date(prev.loadedAt).toLocaleString('fr-FR', { timeZone: 'Europe/Paris' })} conservées.`].concat(P.errors.slice(0, 5));
  flow.set('lv_M', prev);
  const texte = ['=== Livraisons : rechargement en ÉCHEC, ancien modèle conservé ===', ...P.errors, ...P.alerts].join('\n');
  node.warn(texte);
  node.status({ fill: 'red', shape: 'ring', text: `échec ${P.errors.length} requêtes, ancien modèle conservé` });
  return { payload: { resume: 'échec, ancien modèle conservé', texte, errors: P.errors } };
}

// 2. Construction
let res;
try { res = buildModel(raw, C); } catch (e) {
  node.error('Livraisons : construction du modèle en erreur : ' + e.stack, msg);
  return null;
}
const { M, J } = res;
M.erreurs = (P.errors || []).length ? ['Données incomplètes : ' + P.errors.length + ' requêtes BC en échec (voir le journal).'].concat(P.errors.slice(0, 5)) : [];
M.controle.collecte = { ms: P.ms, pages: P.pages, origine: P.origine, alertes: P.alerts || [], stats: Object.keys(P.stats || {}).map(k => ({ ent: (P.E && P.E[k] ? P.E[k].ent : k), n: P.stats[k] })) };
flow.set('lv_M', M);
J.collecte = { ms: P.ms, pages: P.pages, origine: P.origine, erreurs: P.errors, alertes: P.alerts };
flow.set('lv_J', J);

// 3. Journal lisible
const soc = C.soc.map(s => s.court);
const L = [];
L.push(`=== Livraisons : chargement ${P.origine} du ${new Date().toLocaleString('fr-FR', { timeZone: 'Europe/Paris' })} ===`);
L.push(`Collecte ${Math.round(P.ms / 1000)} s (${P.pages} pages), construction ${J.ms} ms`);
L.push('', 'Volumes BC (lignes reçues par entité) : ' + soc.join(' | '));
for (const k in P.stats) L.push(`  ${(P.E && P.E[k] ? P.E[k].ent : k).padEnd(38)} ${P.stats[k].map(fr).join(' | ')}`);
if (J.dedup.length) { L.push('', 'Doublons inter-sociétés retirés (tables partagées) :'); J.dedup.forEach(d => L.push(`  ${d.entite} : ${fr(d.retires)} (${d.detail.join(', ')})`)); }
L.push('', 'Sources :');
for (const k in M.controle.sources) {
  const s = M.controle.sources[k], R = s.remplissage;
  L.push(`  ${s.lib.padEnd(20)} ${fr(s.docs)} documents, ${fr(s.lignes)} lignes, ${fr(s.t)} t, du ${s.dMin} au ${s.dMax} ; chauffeur ${R.chauf}, véhicule ${R.veh}, code postal ${R.cp}, commune ${R.ville}`);
  s.poids.forEach(p => L.push(`      poids : ${p.s} ${fr(p.lignes)} lignes, ${fr(p.t)} t`));
}
L.push('', `Référentiels : ${Object.entries(M.controle.referentiels).map(([k, v]) => k + ' ' + fr(v)).join(', ')} ; carnet : ${M.controle.carnet.missions} missions à planifier, ${M.controle.carnet.commandes} lignes de commande`);
L.push('', 'Rejets :'); Object.entries(J.rejets).sort((a, b) => b[1] - a[1]).forEach(([k, v]) => L.push(`  ${k} : ${fr(v)}`));
