  // ponctualité : date réalisée (tournée, pesée ou BL) contre date demandée ou prévue
  function tabDelais(X, cur) {
    const { M } = X;
    const docs = new Map();
    for (const f of cur.lines) { const k = X.bk(f); if (!X.liv(k)) continue; const x = docs.get(k) || { kg: 0 }; x.kg += f.kg; docs.set(k, x); }
    const B = [['En avance', -1e9, -1], ['Le jour prévu', 0, 0], ['1 jour de retard', 1, 1], ['2 à 3 jours', 2, 3], ['4 à 7 jours', 4, 7], ['8 à 14 jours', 8, 14], ['15 jours et plus', 15, 1e9]];
    const bk = B.map(([l]) => ({ l, n: 0, kg: 0 }));
    const ecarts = [], late = [], parS = {}, parC = {}, parV = {};
    for (const [k, x] of docs) {
      const h = X.D.docs[k]; if (!h || !h.dCible) continue;
      const e = diffD(h.dCible, h.d); ecarts.push(e);
      const i = B.findIndex(b => e >= b[1] && e <= b[2]); bk[i].n++; bk[i].kg += x.kg;
      for (const [P, key, labF] of [[parS, h.sect, lab], [parC, h.chauf, X.chauf], [parV, M.pfs[h.pf], v => v]]) { const y = P[key] || (P[key] = { l: labF(key), code: key, n: 0, ok: 0, r: 0 }); y.n++; if (e > 0) y.r += e; else y.ok++; }
      if (e > 0) late.push({ pf: M.pfs[h.pf], no: h.no, d: h.d, cible: h.dCible, retard: e, code: h.cli, nom: X.nom(h.cli), ville: h.ville, sect: lab(h.sect), chauf: X.chauf(h.chauf), t: r3(x.kg / 1000) });
    }
    const blocks = [];
    if (!ecarts.length) blocks.push(N('dl_vide', X.F.source === 'pesees' ? 'Les pesées n\'ont pas de date demandée : choisir la source Missions (date demandée) ou Bons de livraison (date d\'expédition prévue).' : 'Aucune date demandée ou prévue sur les documents de la période.', 'warn'));
    ecarts.sort((a, b) => a - b);
    const ok = ecarts.filter(e => e <= 0).length;
    const pRows = P => Object.values(P).map(y => ({ code: y.code, l: y.l, n: y.n, ok: y.ok, pct: div(y.ok, y.n), retard: r2(div(y.r, y.n - y.ok)) })).sort((a, b) => b.n - a.n);
    const cols = l => [c('l', l), c('n', 'Avec date cible', 'int'), c('ok', 'À l\'heure', 'int'), c('pct', 'Ponctualité', 'pct'), c('retard', 'Retard moyen (j)', 'num')];
    blocks.push(
      { type: 'kpis', id: 'dl_k', w: 12, items: [
        { k: 'n', l: `${X.SRC.lib} avec date cible`, v: ecarts.length, f: 'int', sub: { t: '{v} de la période', v: div(ecarts.length, docs.size), f: 'pct' } },
        { k: 'ponct', l: 'À la date prévue ou en avance', v: div(ok, ecarts.length), f: 'pct' },
        { k: 'ret', l: 'En retard', v: late.length, f: 'int', good: -1, sub: { t: 'retard moyen {v}', v: r2(div(sum(late, x => x.retard), late.length)), f: 'days' } },
        { k: 'med', l: 'Écart médian', v: ecarts.length ? ecarts[Math.floor((ecarts.length - 1) / 2)] : null, f: 'days', good: -1 }
      ] },
      { type: 'chart', id: 'dl_bk', title: 'Écart entre date réalisée et date demandée ou prévue', cats: bk.map(b => b.l), xcatF: 'txt', catT: 'Écart', series: [{ n: X.SRC.lib, d: bk.map(b => b.n), c: COL.a }], f: 'int', w: 6, xl: false },
      T('dl_bk_t', 'Répartition des écarts', [c('l', 'Écart'), c('n', X.SRC.lib, 'int'), c('p', 'Part', 'pct'), c('t', 'Tonnes', 'ton')], bk.map(b => ({ l: b.l, n: b.n, p: div(b.n, ecarts.length), t: r3(b.kg / 1000) })), { w: 6, nopage: true, main: true }),
      T('dl_sect', 'Ponctualité par secteur', cols('Secteur'), pRows(parS), { w: 4, click: 'secteur' }),
      T('dl_ch', 'Ponctualité par chauffeur', cols('Chauffeur'), pRows(parC), { w: 4, click: 'chauffeur' }),
      T('dl_soc', 'Ponctualité par société', cols('Société'), pRows(parV), { w: 4, nopage: true }),
      T('dl_late', 'En retard sur la date demandée ou prévue', [c('pf', 'Société'), c('no', X.SRC.doc, 'code'), c('d', 'Réalisé le', 'date'), c('cible', 'Date cible', 'date'), c('retard', 'Retard (j)', 'int'), c('code', 'Client', 'code'), c('nom', 'Nom'), c('ville', 'Commune'), c('sect', 'Secteur'), c('chauf', 'Chauffeur'), c('t', 'Tonnes', 'ton')], late, { click: 'client', sort: 'retard', pp: 25 })
