    const parK = keyF => { const o = {}; for (const l of L) { const k = keyF(l); const x = o[k] || (o[k] = { k, kg: 0, n: new Set(), lg: 0, late: 0, ht: 0, u: {} }); x.kg += l.kg; x.lg++; x.ht += l.ht; x.n.add(l.pf + '|' + l.no); if (l.u || l.qr) x.u[l.u] = (x.u[l.u] || 0) + l.qr; if (l.dPrev && l.dPrev < today) x.late += l.kg; } return Object.values(o).sort((a, b) => b.kg - a.kg || b.lg - a.lg); };
