    const colsK = [c('n', 'Documents', 'int'), c('lg', 'Lignes', 'int'), c('qte', 'Quantités par unité'), c('t', 'Tonnes', 'ton'), c('part', 'Part', 'pct'), c('tLate', 'dont en retard (t)', 'ton'), c('ht', 'Valeur HT', 'eur')];
