        { k: 'cmd', l: 'Commandes à livrer', v: new Set(L.filter(l => l.src !== 'Mission à planifier').map(l => l.pf + '|' + l.no)).size, f: 'int', sub: { t: '{v} lignes', v: L.filter(l => l.src !== 'Mission à planifier').length, f: 'int' } },
