        { k: 'd7', l: 'Prévues sous 7 jours', v: new Set(d7.map(l => l.pf + '|' + l.no)).size, f: 'int', sub: { t: '{v}', v: r3(sum(d7, l => l.kg) / 1000), f: 'ton' } },
        { k: 'sd', l: 'Sans date', v: new Set(sd.map(l => l.pf + '|' + l.no)).size, f: 'int', good: -1 }
      ] },
      { type: 'chart', id: 'cr_sem', title: 'En attente par semaine demandée ou prévue', cats: ordre.map(k => (k.includes('-S') ? k.slice(2) : k)), xcatF: 'txt', catT: 'Semaine', series: [{ n: 'Documents', d: ordre.map(k => sem[k].n.size), c: COL.a }, { n: 'Tonnes', d: ordre.map(k => r3(sem[k].kg / 1000)), c: COL.b, kind: 'line', ax: 2 }], f: 'int', f2: 'ton', w: 12 },
      T('cr_src', 'Par nature', [c('lib', 'Nature')].concat(colsK), parK(l => l.src).map(x => rowK(x, { lib: x.k })), { w: 6, nopage: true }),
      T('cr_sect', 'Par secteur', [c('lib', 'Secteur')].concat(colsK), parK(l => l.sect).map(x => rowK(x, { code: x.k, lib: lab(x.k) })), { w: 6, click: 'secteur', sort: 't' }),
      T('cr_cli', 'Par client', [c('code', 'Code', 'code'), c('nom', 'Client')].concat(colsK), parK(l => l.cli).map(x => rowK(x, { code: x.k, nom: X.nom(x.k) })), { w: 6, click: 'client', sort: 't' }),
