try {
  switch (action) {

    case 'meta':
      return repondre(200, { etat: etat(), admin: admin, pfs: M ? M.pfs : [], pfNoms: M ? M.pfNoms : [] });

    case 'statut':
      return repondre(200, { etat: etat(), admin: admin });

    case 'requete': {
      if (!M) return repondre(200, { nodata: true, etat: etat() });
      const data = LVE.compute(M, corps.filtres || {}, { today });
      data.etat = etat();
      for (const onglet in data.tabs) data.tabs[onglet] = alleger(data.tabs[onglet]);
      node.status({ fill: 'green', shape: 'dot', text: 'data-tools : calcul ' + data.meta.ms + ' ms (' + (utilisateur.login || '?') + ')' });
      return repondre(200, data);
    }

    case 'fiche': {
      if (!M) return refuser(409, 'aucune_donnee', 'Aucune donnée chargée.');
      const kind = String(corps.kind || '');
      if (!LVE.KINDS[kind]) return refuser(400, 'fiche_inconnue', 'Type de fiche inconnu : ' + kind);
      const code = String(corps.code || '').trim();
      if (!code) return refuser(400, 'code_manquant', 'Code manquant.');
      const f = LVE.fiche(M, corps.filtres || {}, kind, code, { today });
      return repondre(200, { kind: kind, code: code, title: f.title, blocks: alleger(f.blocks) });
    }

    case 'export': {
      if (!M) return refuser(409, 'aucune_donnee', 'Aucune donnée chargée.');
      const dataXl = LVE.compute(M, corps.filtres || {}, { today, xl: true });
      msg.payload = { data: dataXl, brut: corps.brut !== false };
      return [msg, null, null];
    }

    case 'recharger': {
      if (methode !== 'POST') return refuser(405, 'methode', 'POST attendu.');
      if (!admin) return refuser(403, 'admin_requis', 'Rechargement réservé aux administrateurs.');
      const R = flow.get('lv_run');
      if (R && !R.fini && Date.now() - R.t0 < CHARGEMENT_MAX_MS) {
        return refuser(409, 'chargement_en_cours', 'Un chargement BC est déjà en cours (' + (R.done || 0) + '/' + (R.total || 0) + ' requêtes).');
      }
      node.warn('Livraisons : rechargement BC demandé par ' + (utilisateur.login || '?') + ' (data-tools)');
      msg.statusCode = 202;
      msg.payload = { lance: true, message: 'Chargement BC lancé' };
      msg.headers = { 'Cache-Control': 'no-store' };
      return [null, { topic: 'data-tools' }, msg];
    }

    default:
      return refuser(404, 'action_inconnue', 'Action inconnue : ' + action);
  }
} catch (e) {
  node.error('Livraisons data-tools : ' + (e.stack || e), msg);
  return refuser(500, 'erreur_calcul', 'Erreur de calcul : ' + e.message);
}

