  if (o.main) {
    S.ws.views = [{ state: 'frozen', xSplit: 0, ySplit: r0, topLeftCell: 'A' + (r0 + 1), activeCell: 'A' + (r0 + 1) }];
    S.ws.autoFilter = { from: { row: r0, column: 1 }, to: { row: Math.max(r0, S.r - 1), column: cols.length } };
  }
  S.r++;
}

function fmtTxt(v, f) {
  if (v === null || v === undefined) return 'n.d.';
  const nf = (x, a, b) => Number(x).toLocaleString('fr-FR', { minimumFractionDigits: a, maximumFractionDigits: b });
  if (f === 'eur') return nf(v, 2, 2) + ' €'; if (f === 'eur0') return nf(v, 0, 0) + ' €'; if (f === 'pct') return nf(v * 100, 1, 1) + ' %';
  if (f === 'ton') return nf(v, 1, 1) + ' t'; if (f === 'days') return nf(v, 0, 1) + ' j';
  if (f === 'int') return nf(v, 0, 0); if (f === 'date') return String(v).split('-').reverse().join('/');
  return typeof v === 'number' ? nf(v, 0, 2) : String(v);
}
function ecart(it, ref) {
  if (ref === null || ref === undefined || it.v === null || it.v === undefined) return { v: null, f: 'pct' };
  if (it.f === 'pct') return { v: Math.round((it.v - ref) * 1000) / 10, f: 'pts' };
  return { v: ref ? (it.v - ref) / Math.abs(ref) : null, f: 'pct' };
}
function kpiTable(S, b, meta) {
  if (b.title) text(S, b.title, ST.soustitre);
  const avecP = b.items.some(i => i.p !== null && i.p !== undefined), avecN = b.items.some(i => i.n1 !== null && i.n1 !== undefined);
  const cols = ['Indicateur', 'Valeur'].concat(avecP ? [`Période préc. (${fmtTxt(meta.pdu, 'date')} au ${fmtTxt(meta.pau, 'date')})`, 'Variation'] : [], avecN ? [`N-1 (${fmtTxt(meta.ndu, 'date')} au ${fmtTxt(meta.nau, 'date')})`, 'Variation N-1'] : [], ['Détail']);
  cols.forEach((t, i) => { put(S, S.r, i + 1, t, ST.head); width(S, i + 1, Math.min(t.length, 24)); });
  S.r++;
  b.items.forEach((it, j) => {
    const z = j % 2 === 1; let c = 1;
    put(S, S.r, c, it.l, st('txt', z)); width(S, c++, it.l.length);
    const vv = val(it.v, it.f); put(S, S.r, c, vv, st(it.f, z)); width(S, c++, dispLen(vv, it.f));
    for (const [ok, ref] of [[avecP, it.p], [avecN, it.n1]]) {
      if (!ok) continue;
      const pv = val(ref, it.f); put(S, S.r, c, pv, st(it.f, z)); width(S, c++, dispLen(pv, it.f));
      const e = ecart(it, ref); put(S, S.r, c, e.v, st(e.f, z)); width(S, c++, 10);
    }
    const sub = it.sub ? String(it.sub.t).replace('{v}', it.sub.v === undefined ? '' : fmtTxt(it.sub.v, it.sub.f)) : '';
    put(S, S.r, c, sub || null, st('txt', z)); width(S, c, sub.length);
    S.r++;
  });
  S.r++;
}
function chartTable(S, b) {
  const cats = b.xcats || b.cats || [];
  const cf = b.xcatF === 'date' ? 'date' : b.xcatF === 'code' ? 'code' : 'txt';
  const cols = [{ k: 'c', t: b.catT || 'Catégorie', f: cf }].concat(b.series.map((s, i) => ({ k: 's' + i, t: s.n, f: s.ax === 2 ? b.f2 || 'num' : b.f || 'num' })));
  const rows = cats.map((c, j) => { const r = { c }; b.series.forEach((s, i) => { const d = s.xd || s.d; r['s' + i] = d[j]; }); return r; });
  table(S, cols, rows, { title: b.title });
}
function hbarTable(S, b) {
  const rows = (b.xrows || b.rows).map(r => ({ l: r.l, v: r.v, p: r.p }));
  if (b.xrows) { const tot = rows.reduce((a, r) => a + (Number(r.v) || 0), 0); rows.forEach(r => (r.p = tot ? r.v / tot : null)); }
  table(S, [{ k: 'l', t: 'Libellé', f: 'txt' }, { k: 'v', t: b.f === 'int' ? 'Livraisons' : 'Tonnes', f: b.f || 'ton' }, { k: 'p', t: 'Part', f: 'pct' }], rows, { title: b.title });
}
function heatTable(S, b) {
  const fm = b.fm || 'num';
  const cols = [{ k: 'j', t: '', f: 'txt' }].concat(b.cols.map((c, i) => ({ k: 'h' + i, t: c, f: fm })), [{ k: 'tot', t: 'Total', f: fm }]);
  const rows = b.rows.map((j, r) => { const o = { j, tot: 0 }; b.cols.forEach((c, i) => { o['h' + i] = b.m[r][i] || null; o.tot += b.m[r][i] || 0; }); return o; });
  table(S, cols, rows, { title: b.title + (fm === 'ton' ? ' (tonnes)' : '') });
  const rowsN = b.rows.map((j, r) => { const o = { j, tot: 0 }; b.cols.forEach((c, i) => { o['h' + i] = b.n[r][i] || null; o.tot += b.n[r][i] || 0; }); return o; });
  table(S, cols.map(c => (c.f === fm ? Object.assign({}, c, { f: 'int' }) : c)), rowsN, { title: b.title + ' (' + (b.nl || 'nombre') + ')' });
}
function blocks(S, list, meta) {
  const bl = list.filter(b => b.xl !== false);
  const main = bl.find(b => b.type === 'table' && b.main);
  const ordered = main ? [main].concat(bl.filter(b => b !== main)) : bl;
  const notes = [];
  for (const b of ordered) {
    if (b.type === 'note') { notes.push(b.text); continue; }
    if (b.type === 'table') table(S, b.cols, b.rows, { title: b === main ? null : b.title, main: b === main });
    else if (b.type === 'kpis') kpiTable(S, b, meta);
    else if (b.type === 'chart') chartTable(S, b);
    else if (b.type === 'hbar') hbarTable(S, b);
    else if (b.type === 'heat') heatTable(S, b);
  }
  if (main) { S.ws.getRow(1).height = 28; }
  notes.forEach(t => text(S, t, ST.note));
}
function finish(S) { S.w.forEach((w, i) => { if (w) S.ws.getColumn(i).width = w; }); }

// données BC brutes : écriture rapide (pas de style par cellule)
const BRUT_MAX = 1000000;
function feuilleBrute(wb, nom, t) {
  const ws = wb.addWorksheet(nom);
  const head = ws.addRow(t.cols);
  head.eachCell(cell => { cell.style = ST.head; });
  head.height = 28;
  const iso = /^\d{4}-\d{2}-\d{2}$/;
  const n = Math.min(t.rows.length, BRUT_MAX);
  for (let i = 0; i < n; i++) {
    ws.addRow(t.rows[i].map(v => (typeof v === 'string' && iso.test(v) ? (v > '1900-01-01' ? new Date(v + 'T00:00:00Z') : null) : v)));
  }
  t.cols.forEach((c, i) => {
    const col = ws.getColumn(i + 1);
    col.width = Math.min(40, Math.max(10, String(c).length + 2));
    col.font = FONT;
    if (t.rows.length && t.rows.slice(0, 50).some(r => typeof r[i] === 'string' && iso.test(r[i]))) col.numFmt = 'dd/mm/yyyy';
  });
  ws.views = [{ state: 'frozen', xSplit: 0, ySplit: 1, topLeftCell: 'A2', activeCell: 'A2' }];
  ws.autoFilter = { from: { row: 1, column: 1 }, to: { row: Math.max(1, n + 1), column: t.cols.length } };
  if (t.rows.length > BRUT_MAX) ws.addRow([`Tronqué : ${t.rows.length} lignes, ${BRUT_MAX} écrites. Réduire la période.`]);
}

(async () => {
  try {
    if (!data || !data.tabs) throw new Error('données absentes');
    const wb = new ExcelJS.Workbook();
    wb.creator = 'Node-RED Livraisons'; wb.created = new Date();

    // Synthèse
    const S0 = newSheet(wb, 'Synthèse');
    text(S0, 'Transport et livraisons : synthèse', ST.titre); S0.r++;
    text(S0, 'Filtres', ST.soustitre);
    data.resume.forEach(([k, v], j) => { put(S0, S0.r, 1, k, ST.gras); put(S0, S0.r, 2, String(v), st('txt', j % 2 === 1)); width(S0, 1, k.length); width(S0, 2, Math.min(60, String(v).length)); S0.r++; });
    S0.r++;
    blocks(S0, data.tabs.vue, data.meta);
    finish(S0);

    const map = [['Secteurs', 'secteurs'], ['Chauffeurs', 'chauffeurs'], ['Clients', 'clients'], ['Articles', 'articles'], ['Temps', 'temps'], ['Sociétés', 'societes'], ['Délais', 'delais'], ['Carnet à livrer', 'carnet'], ['Documents', 'livraisons'], ['Lignes', 'lignes'], ['Contrôle', 'controle']];
    for (const [nom, k] of map) {
      const S = newSheet(wb, nom);
      blocks(S, data.tabs[k] || [], data.meta);
      finish(S);
    }
    if (avecBrut && data.brut) {
      feuilleBrute(wb, ('BC ' + data.brut.nom).slice(0, 31), data.brut.entetes);
      if (data.brut.lignes) feuilleBrute(wb, 'BC lignes des BL', data.brut.lignes);
    }
    const buf = await wb.xlsx.writeBuffer();
    const name = `Livraisons_${data.meta.source}_${data.meta.du}_${data.meta.au}.xlsx`;
    node.status({ fill: 'green', shape: 'dot', text: `${name} ${Math.round(buf.byteLength / 1024)} Ko` });
    msg.payload = Buffer.from(buf);
    msg.statusCode = 200;
    msg.headers = {
      'Content-Type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      'Content-Disposition': 'attachment; filename="' + name + '"; filename*=UTF-8\'\'' + encodeURIComponent(name),
      'Cache-Control': 'no-store'
    };
    node.send(msg);
  } catch (e) {
    node.error('Livraisons export Excel : ' + (e.stack || e), msg);
    msg.statusCode = 500;
    msg.payload = { erreur: 'export_impossible', message: 'Export Excel en erreur : ' + e.message };
    msg.headers = { 'Cache-Control': 'no-store' };
    node.send(msg);
  } finally {
    node.done();
  }
})();
return;
